    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.closes = {
            symbol: RollingWindow[float](101)
            for symbol in self.symbols.values()
        }

        self.aapl_red_streak = 0
        self.aapl_rsi = None
        self.aapl_rsi_samples = 0
        self.aapl_initial_gains = []
        self.aapl_initial_losses = []
        self.aapl_avg_gain = None
        self.aapl_avg_loss = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                close = float(data.Bars[symbol].Close)

                if symbol == self.aapl:
                    self._UpdateAaplState(close)

                self.closes[symbol].Add(close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self.closes[self.spy].IsReady or not self.closes[self.aapl].IsReady:
            return

        if self.aapl_rsi is None:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_sma_today = sum(self.closes[self.spy][i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.closes[self.spy][i] for i in range(1, 101)) / 100.0
        spy_yesterday_close = self.closes[self.spy][1]

        spy_crosses_above = (
            spy_yesterday_close <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_yesterday_close >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            shares = int((float(self.Portfolio.TotalPortfolioValue) * 0.40) // spy_close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20000:
                shares = int(20000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _UpdateAaplState(self, close):
        window = self.closes[self.aapl]

        if window.Count > 0:
            previous_close = window[0]
            change = close - previous_close

            if change < 0:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.aapl_rsi_samples < 14:
                self.aapl_initial_gains.append(gain)
                self.aapl_initial_losses.append(loss)
                self.aapl_rsi_samples += 1

                if self.aapl_rsi_samples == 14:
                    self.aapl_avg_gain = sum(self.aapl_initial_gains) / 14.0
                    self.aapl_avg_loss = sum(self.aapl_initial_losses) / 14.0
                    self.aapl_rsi = self._CalculateRsi()
            else:
                self.aapl_avg_gain = ((self.aapl_avg_gain * 13.0) + gain) / 14.0
                self.aapl_avg_loss = ((self.aapl_avg_loss * 13.0) + loss) / 14.0
                self.aapl_rsi = self._CalculateRsi()

    def _CalculateRsi(self):
        if self.aapl_avg_loss == 0:
            return 100.0
        if self.aapl_avg_gain == 0:
            return 0.0

        rs = self.aapl_avg_gain / self.aapl_avg_loss
        return 100.0 - (100.0 / (1.0 + rs))
